// js
const entry = get(ctx, 'entry', {});
const kind = String(get(entry, 'kind', 'NORMAL_DAY'));
const day = get(ctx.lookup.overtime_multiples, kind, 1);
// Labour Code 45/2019/QH14 art.98(3): 20% of that day's daytime wage; on a weekly rest day the employer's rest-day hourly multiple stands where it pays more.
return ctx.hour_rate * Number(get(entry, 'quantity', 0)) * ctx.lookup.multiplier * (kind === 'REST_DAY' ? Math.max(day, Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0))) : day);
